void scriptResetRun(scriptRunCtx *run_ctx) {
    serverAssert(curr_run_ctx);

    /* After the script done, remove the MULTI state. */
    run_ctx->c->flag.multi = 0;

    if (scriptIsTimedout()) {
        exitScriptTimedoutMode(run_ctx);
